            raise TypeError(
                "%s 的 %s 必须是 int，得到 %s"
                % (name, member_name, type(member).__name__)
            )
        if member <= 0:
            raise ValueError("%s 的 %s 必须为正整数" % (name, member_name))
    return (kh_, kw_)


