    conv, bn, dropout, pool, _flatten, linear, _loss = layers

    if conv._w_shape != _CKPT_CONV_W_SHAPE:
        raise ValueError(
            "Conv2D weights 形状必须为 [2][1][1][1]，得到 %s"
            % (conv._w_shape,)
        )
    if conv._stride != (1, 1):
        raise ValueError("Conv2D stride 必须与 fitnorm 一致（1, 1）")
