        raise ValueError("Conv2D dilation 必须与 fitnorm 一致（1）")
    if conv._groups != 1:
        raise ValueError("Conv2D groups 必须与 fitnorm 一致（1）")
    if conv._padding_mode != "zeros":
        raise ValueError(
            "Conv2D padding_mode 必须与 fitnorm 一致（zeros），得到 %r"
            % conv._padding_mode
